{
  "title": "夜幕下的数据港",
  "scene": "你站在一座巨大的数据港前，周围霓虹灯闪烁，映照出未来都市的繁华与冷漠。这里是巨型企业‘赛博核心’的中心，你此行的目的地。数据港的入口处有两个守卫，他们都装备了最新的义体，看起来无法轻易突破。不远处，一位神秘的黑客正倚靠在墙边，似乎在等待着什么。突然，你注意到其中一个守卫的义体似乎有些故障，偶尔会发出轻微的‘咔哒’声，这可能是一个机会。你可以尝试与黑客交谈，看看他是否能提供帮助；或者直接尝试闯过去，利用义体故障的机会；还可以选择绕路，寻找数据港的其他入口。",
  "goal": "潜入数据港",
  "clue": "义体故障",
  "choices": [
    {
      "id": "A",
      "text": "与黑客交谈",
      "outcome": "黑客狐疑地打量了你一番，最终同意联手。他使用自己的技能暂时瘫痪了守卫的系统，你顺利潜入了数据港。不过，黑客要求你事后帮他一个忙。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "利用义体故障",
      "outcome": "你趁守卫不注意，轻手轻脚地接近了义体故障的那个守卫。幸运的是，故障影响了他的反应速度，你成功绕过了他们，进入了数据港。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "绕路寻找其他入口",
      "outcome": "你沿着数据港外围走了一圈，但发现所有入口都装有先进的安全系统，无法轻易绕过。守卫的巡逻也更加频繁，你不得不退回原处，重新思考计划。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
